"s4.top.smartSolarSeedSowerA": "ಸ್ಮಾರ್ಟ್ ಸೋಲಾರ್ ಬೀಜ ಬಿತ್ತನೆ ಯಂತ್ರ — ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಿಗೆ ನೆರವಾಗಲು ರೂಪಿಸಿದ, ಬೆನ್ನಿಗೆ ಹಾಕಿಕೊಳ್ಳುವ, ಹೊತ್ತೊಯ್ಯಬಹುದಾದ ಬೀಜ ಬಿತ್ತನೆ ವ್ಯವಸ್ಥೆ.",
"s4.top.bhoomishaktiS4CombinesSolarEnergy": "“BhoomiShakti S4 ಸೋಲಾರ್ ಶಕ್ತಿ, ಜಾಣ ಬೀಜ ಹರಿವು ನಿಯಂತ್ರಣ ಮತ್ತು ಹೊತ್ತೊಯ್ಯಬಹುದಾದ ವಿನ್ಯಾಸವನ್ನು ಸೇರಿಸಿ ಬೀಜ ಬಿತ್ತನೆಯನ್ನು ಹೆಚ್ಚು ಸಮರ್ಥ, ಕಡಿಮೆ ಖರ್ಚಿನ ಮತ್ತು ರೈತ ಸ್ನೇಹಿಯಾಗಿಸುತ್ತದೆ.”",
