"jeevadhara.overview.highLabourRequirementForOrganic": "ಸಾವಯವ ಕೃಷಿಗೆ ಹೆಚ್ಚು ಕೂಲಿ ಬೇಕು",
"jeevadhara.overview.unevenNutrientDistribution": "ಪೋಷಕಾಂಶಗಳು ಸಮವಾಗಿ ಹರಡುವುದಿಲ್ಲ",
"jeevadhara.overview.aControlledBionutrientSystemX1": "ನಿಯಂತ್ರಿತ ಜೈವಿಕ ಪೋಷಕಾಂಶ ವ್ಯವಸ್ಥೆ + X1",
"jeevadhara.overview.agedManureCompostSoilCocopeat": "ಹಳೆಯ ಗೊಬ್ಬರ, ಕಾಂಪೋಸ್ಟ್, ಮಣ್ಣು, ಕೊಕೊಪೀಟ್ ಮತ್ತು ನೀರು ಬೆರೆಸಿದ ಮೂತ್ರವನ್ನು ನಿಯಂತ್ರಿತ ಜೈವಿಕ ಪೋಷಕಾಂಶ ಮಿಶ್ರಣವಾಗಿ ತಯಾರಿಸಿ, ಹದಗೊಳಿಸಿ, ನಂತರ BhoomiShakti X1 ಬಳಸಿ ಮಣ್ಣಿಗೆ ಬೆರೆಸಲಾಗುತ್ತದೆ.",
"jeevadhara.overview.objectives": "ಉದ್ದೇಶಗಳು",
"jeevadhara.overview.developAControlledBionitrogenSystem": "ನಿಯಂತ್ರಿತ ಜೈವಿಕ ಸಾರಜನಕ ವ್ಯವಸ್ಥೆ ರೂಪಿಸುವುದು",
"jeevadhara.overview.improveSoilBiologicalActivityAnd": "ಮಣ್ಣಿನ ಜೈವಿಕ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಎರೆಹುಳುಗಳಿಗೆ ನೆರವಾಗುವುದು",
"jeevadhara.overview.enhanceSustainableCropProductivity": "ಸುಸ್ಥಿರ ಬೆಳೆ ಇಳುವರಿ ಹೆಚ್ಚಿಸುವುದು",
"jeevadhara.overview.reduceDependenceOnChemicalFertilizers": "ರಾಸಾಯನಿಕ ಗೊಬ್ಬರಗಳ ಮೇಲಿನ ಅವಲಂಬನೆ ಕಡಿಮೆ ಮಾಡುವುದು",
"jeevadhara.overview.reduceManualSoilMixingWith": "BhoomiShakti X1 ಬಳಸಿ ಕೈಯಿಂದ ಮಣ್ಣು ಬೆರೆಸುವುದನ್ನು ಕಡಿಮೆ ಮಾಡುವುದು",
"jeevadhara.simple.howJeevadharaWorksInSimple": "JeevaDhara ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ಸರಳವಾಗಿ",
"jeevadhara.simple.prepareRestMixIn": "ತಯಾರಿಸಿ. ಇಡಿ. <t0>ಬೆರೆಸಿ.</t0>",
"jeevadhara.simple.wePrepareAnOrganicNutrient": "“ನಾವು ಸಾವಯವ ಪೋಷಕಾಂಶ ಮಿಶ್ರಣ ತಯಾರಿಸುತ್ತೇವೆ, ಅದನ್ನು ಹದವಾಗಲು ಬಿಡುತ್ತೇವೆ, ನಂತರ BhoomiShakti X1 ಬಳಸಿ ಅದನ್ನು ಮಣ್ಣಿಗೆ ಹೆಚ್ಚು ಸಮರ್ಥವಾಗಿ ಬೆರೆಸುತ್ತೇವೆ.”",
