"jeevadhan.overview.fromAWasteChallengeTo": "ತ್ಯಾಜ್ಯದ ಸಮಸ್ಯೆಯಿಂದ <t0>ಹಳ್ಳಿಯ ಮೌಲ್ಯದವರೆಗೆ.</t0>",
"jeevadhan.overview.aProposedCircularBiomasstoresourceEcosystem": "ಜಾನುವಾರು, ರೈತರು, ಹಳ್ಳಿಯ ಜೈವಿಕ ತ್ಯಾಜ್ಯ, ನವೀಕರಿಸಬಹುದಾದ ಶಕ್ತಿ, ಕೃಷಿ ಮತ್ತು ಡಿಜಿಟಲ್ ತಂತ್ರಜ್ಞಾನವನ್ನು ಜೋಡಿಸುವ ಪ್ರಸ್ತಾಪಿತ ಮರುಬಳಕೆ ವ್ಯವಸ್ಥೆ — ಜೈವಿಕ ತ್ಯಾಜ್ಯದಿಂದ ಸಂಪನ್ಮೂಲ.",
"jeevadhan.overview.ruralBiomassIsUnderutilized": "ಹಳ್ಳಿಯ ಜೈವಿಕ ತ್ಯಾಜ್ಯ ಸರಿಯಾಗಿ ಬಳಕೆಯಾಗುತ್ತಿಲ್ಲ",
