"jeevadhan.overview.dependenceOnConventionalEnergySources": "ಸಾಂಪ್ರದಾಯಿಕ ಶಕ್ತಿ ಮೂಲಗಳ ಮೇಲೆ ಅವಲಂಬನೆ",
"jeevadhan.overview.noOrganizedDigitalBiomassNetwork": "ವ್ಯವಸ್ಥಿತ ಡಿಜಿಟಲ್ ಜೈವಿಕ ತ್ಯಾಜ್ಯ ಜಾಲ ಇಲ್ಲ",
"jeevadhan.overview.needForSustainableOrganicresourceManagement": "ಸಾವಯವ ಸಂಪನ್ಮೂಲಗಳ ಸುಸ್ಥಿರ ನಿರ್ವಹಣೆಯ ಅಗತ್ಯ",
