"jeevadhan.overview.aCircularBiomasstoresourceEcosystem": "ಜೈವಿಕ ತ್ಯಾಜ್ಯದಿಂದ ಸಂಪನ್ಮೂಲ — ಮರುಬಳಕೆ ವ್ಯವಸ್ಥೆ",
"jeevadhan.overview.organizedBiomassCollectionProcessingThrough": "ವ್ಯವಸ್ಥಿತ ಜೈವಿಕ ತ್ಯಾಜ್ಯ ಸಂಗ್ರಹ, ಆಮ್ಲಜನಕರಹಿತ ಜೀರ್ಣಕ್ರಿಯೆಯ ಮೂಲಕ ಸಂಸ್ಕರಣೆ, ನವೀಕರಿಸಬಹುದಾದ ಶಕ್ತಿ ಮಾರ್ಗ ಮತ್ತು ಸ್ಲರಿ ಗೊಬ್ಬರದ ಸೂಕ್ತ ಬಳಕೆ — ರೈತರ ಭಾಗವಹಿಸುವಿಕೆ, ಡಿಜಿಟಲ್ ಮೇಲ್ವಿಚಾರಣೆ ಮತ್ತು ವಹಿವಾಟು ದಾಖಲೆಗಳೊಂದಿಗೆ.",
"jeevadhan.overview.howCanLocallyAvailableCattle": "ಸ್ಥಳೀಯವಾಗಿ ಸಿಗುವ ಜಾನುವಾರು ತ್ಯಾಜ್ಯವನ್ನು ಹೇಗೆ ವ್ಯವಸ್ಥಿತವಾಗಿ ಸಂಗ್ರಹಿಸಿ, ಸಂಸ್ಕರಿಸಿ, ಉಪಯುಕ್ತ ನವೀಕರಿಸಬಹುದಾದ ಶಕ್ತಿ ಮತ್ತು ಕೃಷಿ ಸಂಪನ್ಮೂಲಗಳಾಗಿ ಬದಲಿಸಿ, ಹಳ್ಳಿಯ ಸಮುದಾಯಗಳಿಗೆ ಮೌಲ್ಯ ಸೃಷ್ಟಿಸಬಹುದು?",
