"farmerTools.weather.possibleSprayHoursAreDaytime": "<t0>ಸಿಂಪಡಣೆಗೆ ಸಾಧ್ಯವಿರುವ ಗಂಟೆಗಳು</t0> ಎಂದರೆ ಮಳೆಯ ಮುನ್ಸೂಚನೆ ಇಲ್ಲದ ಮತ್ತು ಗಾಳಿ <t1>{2} ರಿಂದ {3} km/h</t1> ({4}–{5} mph) ನಡುವೆ ಇರುವ ಹಗಲಿನ ಗಂಟೆಗಳು (ಬೆಳಿಗ್ಗೆ {0} – ಸಂಜೆ {1}) — ಇದು ಕೀಟನಾಶಕಗಳ ಜವಾಬ್ದಾರಿಯುತ ಬಳಕೆಯ ಮಾರ್ಗದರ್ಶನದಲ್ಲಿ ಶಿಫಾರಸು ಮಾಡಿರುವ ವ್ಯಾಪ್ತಿ. ಗಾಳಿ ತೀರಾ ನಿಶ್ಚಲವಾಗಿದ್ದರೂ ಔಷಧಿ ಬೇರೆ ಕಡೆಗೆ ಹಾರಬಹುದು.",
