"farmerTools.schemes.linksGoOnlyToOfficial": "ಲಿಂಕ್‌ಗಳು ಭಾರತ ಸರ್ಕಾರದ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್‌ಗಳಿಗೆ ಮಾತ್ರ ಹೋಗುತ್ತವೆ. ಅಧಿಕೃತ ಮೂಲ ಖಚಿತಪಡಿಸಿದ ಸಹಾಯವಾಣಿ ಸಂಖ್ಯೆಗಳನ್ನು ಮಾತ್ರ ತೋರಿಸಲಾಗಿದೆ — ಪ್ರತಿಯೊಂದರ ಜೊತೆ ಅದರ ಮೂಲವನ್ನೂ ತೋರಿಸಲಾಗಿದೆ.",
"farmerTools.schemes.officialGovernmentResource": "<t0/>ಅಧಿಕೃತ ಸರ್ಕಾರಿ ಮಾಹಿತಿ ಮೂಲ",
"farmerTools.schemes.pradhanMantriKisanSammanNidhi": "ಪ್ರಧಾನ ಮಂತ್ರಿ ಕಿಸಾನ್ ಸಮ್ಮಾನ್ ನಿಧಿ",
"farmerTools.schemes.centralGovernmentIncomesupportSchemeFor": "ರೈತ ಕುಟುಂಬಗಳಿಗೆ ಕೇಂದ್ರ ಸರ್ಕಾರದ ಆದಾಯ ಬೆಂಬಲ ಯೋಜನೆ. ನೋಂದಣಿ, eKYC ಮತ್ತು ಫಲಾನುಭವಿ ಸ್ಥಿತಿಯನ್ನು ಅಧಿಕೃತ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ನೋಡಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.",
"farmerTools.schemes.01IvrsHelplineSourcePib": "{0}×{1} IVRS ಸಹಾಯವಾಣಿ · <t0>ಮೂಲ: PIB, ಭಾರತ ಸರ್ಕಾರ ↗</t0>",
"farmerTools.schemes.visitPmkisangovin": "pmkisan.gov.in ಗೆ ಭೇಟಿ ನೀಡಿ <t0/>",
"farmerTools.schemes.pradhanMantriFasalBimaYojana": "ಪ್ರಧಾನ ಮಂತ್ರಿ ಫಸಲ್ ಬಿಮಾ ಯೋಜನೆ (ಬೆಳೆ ವಿಮೆ)",
"farmerTools.schemes.governmentsponsoredCropInsuranceSchemeThe": "ಸರ್ಕಾರಿ ಪ್ರಾಯೋಜಿತ ಬೆಳೆ ವಿಮೆ ಯೋಜನೆ. ಕೃಷಿ ರಕ್ಷಕ್ ಪೋರ್ಟಲ್ ಮತ್ತು ಸಹಾಯವಾಣಿ ಕ್ಲೈಮ್, ದೂರು ಮತ್ತು ಪ್ರಶ್ನೆಗಳಿಗೆ ನೆರವಾಗುತ್ತದೆ.",
"farmerTools.schemes.krishiRakshakPortalHelplineSource": "ಕೃಷಿ ರಕ್ಷಕ್ ಪೋರ್ಟಲ್ ಮತ್ತು ಸಹಾಯವಾಣಿ · <t0>ಮೂಲ: PIB, ಭಾರತ ಸರ್ಕಾರ ↗</t0>",
"farmerTools.schemes.visitPmfbygovin": "pmfby.gov.in ಗೆ ಭೇಟಿ ನೀಡಿ <t0/>",
"farmerTools.schemes.soilHealthCard": "ಮಣ್ಣು ಆರೋಗ್ಯ ಕಾರ್ಡ್",
"farmerTools.schemes.soilHealthCardScheme": "ಮಣ್ಣು ಆರೋಗ್ಯ ಕಾರ್ಡ್ ಯೋಜನೆ",
"farmerTools.schemes.aReportOnYourSoils": "ನಿಮ್ಮ ಮಣ್ಣಿನ ಪೋಷಕಾಂಶಗಳ ಸ್ಥಿತಿಯ ವರದಿ — ಗೊಬ್ಬರ ಮತ್ತು ಮಣ್ಣು ಸುಧಾರಣೆಯ ಶಿಫಾರಸುಗಳ ಜೊತೆ. ಕಾರ್ಡ್ ನೋಡಲು ಮತ್ತು ಪ್ರಿಂಟ್ ಮಾಡಲು ಪೋರ್ಟಲ್ ಬಳಸಲಾಗುತ್ತದೆ.",
"farmerTools.schemes.visitSoilhealthdacgovin": "soilhealth.dac.gov.in ಗೆ ಭೇಟಿ ನೀಡಿ <t0/>",
"farmerTools.schemes.nationalAgricultureMarket": "ರಾಷ್ಟ್ರೀಯ ಕೃಷಿ ಮಾರುಕಟ್ಟೆ",
"farmerTools.schemes.onlineTradingPlatformForAgricultural": "ರಾಜ್ಯಗಳಾದ್ಯಂತ ಮಂಡಿಗಳನ್ನು (APMC) ಜೋಡಿಸುವ, ಕೃಷಿ ಉತ್ಪನ್ನಗಳ ಆನ್‌ಲೈನ್ ವ್ಯಾಪಾರ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್.",
"farmerTools.schemes.tollfreeHelplineSourceEnamgovin": "ಟೋಲ್-ಫ್ರೀ ಸಹಾಯವಾಣಿ · <t0>ಮೂಲ: enam.gov.in ↗</t0>",
"farmerTools.schemes.visitEnamgovin": "enam.gov.in ಗೆ ಭೇಟಿ ನೀಡಿ <t0/>",
"farmerTools.schemes.kisanCallCentre": "ಕಿಸಾನ್ ಕಾಲ್ ಸೆಂಟರ್",
"farmerTools.schemes.kisanCallCentreKcc": "ಕಿಸಾನ್ ಕಾಲ್ ಸೆಂಟರ್ (KCC)",
"farmerTools.schemes.answersFarmersQuestionsOnThe": "ಕೃಷಿ ತಜ್ಞರ ಮೂಲಕ ರೈತರ ಪ್ರಶ್ನೆಗಳಿಗೆ ಅವರದೇ ಭಾಷೆಯಲ್ಲಿ ಫೋನ್‌ನಲ್ಲಿ ಉತ್ತರಿಸುತ್ತದೆ. ವಾರದ ಏಳೂ ದಿನ, ಬೆಳಿಗ್ಗೆ {0}:{1} – ರಾತ್ರಿ {2}:{3} ರವರೆಗೆ ಲಭ್ಯ.",
"farmerTools.schemes.tollfreeSourceMkisangovin": "ಟೋಲ್-ಫ್ರೀ · <t0>ಮೂಲ: mkisan.gov.in ↗</t0>",
"farmerTools.schemes.visitMkisangovin": "mkisan.gov.in ಗೆ ಭೇಟಿ ನೀಡಿ <t0/>",
"farmerTools.schemes.eligibilityBenefitsAndApplicationSteps": "ಅರ್ಹತೆ, ಸೌಲಭ್ಯಗಳು ಮತ್ತು ಅರ್ಜಿ ಹಾಕುವ ಹಂತಗಳು ಬದಲಾಗಬಹುದು. ಇತ್ತೀಚಿನ ವಿವರಗಳಿಗೆ ಯಾವಾಗಲೂ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್ ಅಥವಾ ಸಹಾಯವಾಣಿಯನ್ನು ನೋಡಿ. BhoomiShakti ಗೆ ಈ ಸರ್ಕಾರಿ ಸೇವೆಗಳ ಜೊತೆ ಯಾವುದೇ ಅಧಿಕೃತ ಸಂಬಂಧವಿಲ್ಲ. ಮಾಹಿತಿಯನ್ನು ಅಕ್ಟೋಬರ್ {0} ರಲ್ಲಿ ಪರಿಶೀಲಿಸಲಾಗಿದೆ.",
"farmerTools.main.farmerSafetyInformationNote": "ರೈತರ ಸುರಕ್ಷತೆ ಮತ್ತು ಮಾಹಿತಿ ಸೂಚನೆ",
"farmerTools.main.theseToolsSupportYourDecisions": "ಈ ಸಾಧನಗಳು ನಿಮ್ಮ ನಿರ್ಧಾರಗಳಿಗೆ ನೆರವಾಗುತ್ತವೆ; ಆದರೆ ನಿಮ್ಮ ಸ್ಥಳೀಯ ಕೃಷಿ ಅಧಿಕಾರಿ, ಕೃಷಿ ವಿಜ್ಞಾನ ಕೇಂದ್ರ ಅಥವಾ ಕಿಸಾನ್ ಕಾಲ್ ಸೆಂಟರ್ ({0}-{1}-{2}) ನೀಡುವ ಸಲಹೆಗೆ ಇವು ಬದಲಿ ಅಲ್ಲ.",
"farmerTools.main.beforeSprayingReadAndFollow": "ಸಿಂಪಡಣೆಗೆ ಮೊದಲು ಉತ್ಪನ್ನದ ಲೇಬಲ್ ಓದಿ ಅದರಂತೆ ನಡೆಯಿರಿ, ಮತ್ತು ಅದರಲ್ಲಿ ಹೇಳಿರುವ ರಕ್ಷಣಾ ಸಾಮಗ್ರಿಗಳನ್ನು ಧರಿಸಿ.",
"farmerTools.main.weatherForecastsCanChangeCheck": "ಹವಾಮಾನ ಮುನ್ಸೂಚನೆ ಬದಲಾಗಬಹುದು. ಕೆಲಸದ ದಿನ ಮತ್ತೊಮ್ಮೆ ನೋಡಿ.",
"farmerTools.main.theLandConverterAndProfit": "ಜಮೀನಿನ ಅಳತೆ ಪರಿವರ್ತಕ ಮತ್ತು ಲಾಭದ ಲೆಕ್ಕ ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತವೆ. ನೀವು ಟೈಪ್ ಮಾಡಿದ್ದನ್ನು BhoomiShakti ಪಡೆಯುವುದೂ ಇಲ್ಲ, ಉಳಿಸುವುದೂ ಇಲ್ಲ.",
"farmerTools.contact.moreThanToolsOneEcosystem": "ಸಾಧನಗಳಿಗಿಂತ ಹೆಚ್ಚು — <t0>ಒಂದೇ ವ್ಯವಸ್ಥೆ.</t0>",
"farmerTools.contact.fromAgricultureIntelligenceToSolar": "ಕೃಷಿ ಮಾಹಿತಿಯಿಂದ ಸೋಲಾರ್ ಯಂತ್ರಗಳು ಮತ್ತು ಮಣ್ಣಿನ ಆರೋಗ್ಯದವರೆಗೆ, ರೈತರಿಗೆ ಬೇಕಾದ ಸೇವೆಗಳನ್ನು BhoomiShakti ಜೋಡಿಸುತ್ತದೆ.",
