"team.top.oneFounderSixBuildersAnd": "ಒಬ್ಬ ಸಂಸ್ಥಾಪಕ, ಆರು ಜನ ಕಟ್ಟುವವರು ಮತ್ತು ಎಂಟು ಆವಿಷ್ಕಾರಗಳು. ಇಂಜಿನಿಯರಿಂಗ್, ಸಾಫ್ಟ್‌ವೇರ್, ಮಣ್ಣು ವಿಜ್ಞಾನ ಮತ್ತು ವಿನ್ಯಾಸ — ಎಲ್ಲವೂ ಒಂದೇ ಜೋಡಿಸಿದ ಕೃಷಿ ವ್ಯವಸ್ಥೆಗಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತಿವೆ.",
