"contact.live.sentYourMessageHasBeen": "ಕಳುಹಿಸಲಾಗಿದೆ! ನಿಮ್ಮ ಸಂದೇಶವನ್ನು ಬಿತ್ತಲಾಗಿದೆ.",
"contact.live.sorryTheMessageCouldNot": "ಕ್ಷಮಿಸಿ, ಈಗ ಸಂದೇಶ ಕಳುಹಿಸಲು ಆಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಈ ಪುಟದಲ್ಲಿರುವ ನೇರ ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಬಳಸಿ.",
"contact.live.savedWaitingForInternet": "ಉಳಿಸಲಾಗಿದೆ — ಇಂಟರ್ನೆಟ್‌ಗಾಗಿ ಕಾಯುತ್ತಿದೆ",
"contact.live.yourMessageWillSendWhen": "ಇಂಟರ್ನೆಟ್ ಮರಳಿ ಬಂದಾಗ ನಿಮ್ಮ ಸಂದೇಶ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
"contact.live.youAppearToBeOffline": "ನಿಮಗೆ ಇಂಟರ್ನೆಟ್ ಸಂಪರ್ಕ ಇಲ್ಲದಂತೆ ಕಾಣುತ್ತಿದೆ. ನಿಮ್ಮ ಸಂದೇಶ ಈ ಸಾಧನದಲ್ಲಿ ಉಳಿದಿದೆ; ಸಂಪರ್ಕ ಮರಳಿದಾಗ ತಾನಾಗಿಯೇ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಈ ಪುಟವನ್ನು ತೆರೆದೇ ಇಡಿ.",
"contact.live.plantedAndWaitingForRain": "ಬಿತ್ತಲಾಗಿದೆ, ಮಳೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ — ನೀವು ಆನ್‌ಲೈನ್ ಆದಾಗ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
"diary.top.productConceptFutureFarmerApp": "<t0/>ಉತ್ಪನ್ನ ಪರಿಕಲ್ಪನೆ · ಮುಂದಿನ ರೈತ ಆ್ಯಪ್",
"diary.top.theTaglineInSixIndian": "ಆರು ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ ಘೋಷವಾಕ್ಯ. ಹಿಂದಿ: हर खेत की कहानी, अब आपकी डायरी में. ಕನ್ನಡ: ಪ್ರತಿ ಹೊಲದ ಕಥೆ, ಈಗ ನಿಮ್ಮ ಡೈರಿಯಲ್ಲಿ. ತಮಿಳು: ஒவ்வொரு வயலின் கதையும், இப்போது உங்கள் டைரியில். ತೆಲುಗು: ప్రతి పొలం కథ, ఇప్పుడు మీ డైరీలో. ಮರಾಠಿ: प्रत्येक शेताची कहाणी, आता तुमच्या डायरीत. ಮಲಯಾಳಂ: ഓരോ കൃഷിയിടത്തിന്റെയും കഥ, ഇനി നിങ്ങളുടെ ഡയറിയിൽ.",
"diary.top.yourFarmYourRecordsYour": "ನಿಮ್ಮ ಹೊಲ. ನಿಮ್ಮ ದಾಖಲೆಗಳು. ನಿಮ್ಮ ಪಯಣ.",
"diary.top.bhoomishaktiDiaryIsEnvisionedAs": "ರೈತರು ತಮ್ಮ ದಿನನಿತ್ಯದ ಹೊಲದ ಕೆಲಸ, ಖರ್ಚು, ಬೆಳೆ ದಾಖಲೆ ಮತ್ತು ಹಂಗಾಮಿನ ಇತಿಹಾಸವನ್ನು ಒಂದೇ ಕಡೆ, ತಮ್ಮದೇ ಭಾಷೆಯಲ್ಲಿ ಜೋಡಿಸಿಟ್ಟುಕೊಳ್ಳಲು ನೆರವಾಗುವ ಸರಳ ಡಿಜಿಟಲ್ ಹೊಲದ ಡೈರಿಯಾಗಿ BhoomiShakti Diary ಯನ್ನು ಕಲ್ಪಿಸಲಾಗಿದೆ.",
